import json, sys, re
from collections import Counter

files = [l.strip() for l in open('/tmp/claude-6139/-u-halle-hrm-home-at-Documents-Hackathons-zurich-hackathon/5e44904e-4da9-4a13-baee-4a9340b5da55/scratchpad/transcript_list.txt') if l.strip()]

bash_counter = Counter()
mcp_counter = Counter()

def leading_cmd(cmd):
    cmd = cmd.strip()
    # strip env var prefixes like FOO=bar
    parts = cmd.split()
    i = 0
    while i < len(parts) and re.match(r'^[A-Za-z_][A-Za-z0-9_]*=.*$', parts[i]):
        i += 1
    parts = parts[i:]
    if not parts:
        return None
    # strip sudo/timeout
    while parts and parts[0] in ('sudo', 'timeout'):
        parts = parts[1:]
        # timeout takes a number arg
        if parts and re.match(r'^\d+[smh]?$', parts[0]):
            parts = parts[1:]
    if not parts:
        return None
    base = parts[0]
    sub = parts[1] if len(parts) > 1 and not parts[1].startswith('-') else None
    return base, sub

def split_compound(cmd):
    # split on &&, ||, ; , | but keep it simple
    segments = re.split(r'&&|\|\||;|\|', cmd)
    return [s.strip() for s in segments if s.strip()]

for fp in files:
    try:
        with open(fp, 'r', errors='ignore') as f:
            for line in f:
                line = line.strip()
                if not line:
                    continue
                try:
                    obj = json.loads(line)
                except Exception:
                    continue
                if obj.get('type') != 'assistant':
                    continue
                msg = obj.get('message', {})
                content = msg.get('content', [])
                if not isinstance(content, list):
                    continue
                for c in content:
                    if not isinstance(c, dict):
                        continue
                    if c.get('type') != 'tool_use':
                        continue
                    name = c.get('name', '')
                    inp = c.get('input', {})
                    if name == 'Bash':
                        command = inp.get('command', '')
                        if not command:
                            continue
                        for seg in split_compound(command):
                            r = leading_cmd(seg)
                            if not r:
                                continue
                            base, sub = r
                            key = base if not sub else f"{base} {sub}"
                            bash_counter[key] += 1
                    elif name.startswith('mcp__'):
                        mcp_counter[name] += 1
    except FileNotFoundError:
        continue

print("=== BASH ===")
for k, v in bash_counter.most_common(60):
    print(v, k)
print("=== MCP ===")
for k, v in mcp_counter.most_common(30):
    print(v, k)
